INSERT INTO cocktails (id, slug, name, description, details, image, hero_image, marketing_image, image_cut, glassware, garnish, pairs_with, nutrition_json, alcohol_json, bartesian_url, help_url, shopify_product_id, shopify_variant_id, shopify_handle, shopify_sku, gorgias_article_id, seasonal, favorite, enabled, quantity, restock, created_at, updated_at) VALUES (3, 'amaretto-sour', 'Amaretto Sour', 'The Amaretto Sour pairs nutty almond and orange citrus notes to make for the perfect vodka dessert cocktail. Whether you’re enjoying it for dessert, brunch, or any other time of day, this cocktail is sophisticated and refreshing all at once.', 'Bartesian’s cocktail capsules are a convenient way to make craft cocktails at home with the push of a button. Bartesian’s Amaretto Sour recipe creates a unique flavor profile that is citrusy, nutty, and sweet.
