INSERT INTO cocktails (id, slug, name, description, details, image, hero_image, marketing_image, image_cut, glassware, garnish, pairs_with, nutrition_json, alcohol_json, bartesian_url, help_url, shopify_product_id, shopify_variant_id, shopify_handle, shopify_sku, gorgias_article_id, seasonal, favorite, enabled, quantity, restock, created_at, updated_at) VALUES (4, 'apple-pie', 'Apple Pie', 'Your favorite dessert is now served as a whiskey and vodka cocktail. The sweet combination of baked apple and fall spices is perfectly balanced with hints of lemon and cayenne in our innovative capsules. Wonderfully reminiscent of a slice of grandma''s apple pie. Add this to your collection of whiskey cocktails for holidays, hosting, or any time of year! Base spirits: Whiskey and Vodka.', 'What’s better than a fresh slice of apple pie? A cocktail that evokes warm feelings of seasonal joy, of course! Featuring sweet notes of lemon and apple that pair smoothly to ease the bite of the liquor.
