INSERT INTO cocktails (id, slug, name, description, details, image, hero_image, marketing_image, image_cut, glassware, garnish, pairs_with, nutrition_json, alcohol_json, bartesian_url, help_url, shopify_product_id, shopify_variant_id, shopify_handle, shopify_sku, gorgias_article_id, seasonal, favorite, enabled, quantity, restock, created_at, updated_at) VALUES (8, 'blackberry-mango-refresher', 'Blackberry Mango Refresher (US Only)', 'Some days call for a little extra lift - and this lightly caffeinated Refresher delivers. Juicy, ripe blackberry meets sweet mango in a smooth, fruit-forward blend that’s as vibrant as it is satisfying. With an intentionally lower alcohol level than our other offerings, it’s the kind of drink that keeps things mellow but moving, perfect for powering through the rest of your day without breaking a sweat. Shake and serve over ice in a highball glass, garnished with blackberries.', 'Contains ~55 mg of caffeine. Base spirit: Vodka. Try it as a mocktail!', 'images/marketing/blackberry-mango-refresher.jpg', '', 'images/marketing/blackberry-mango-refresher.jpg', 'NA', 'Highball Glass', 'ed with blackberries', '', '{"label_image":"images/nutrition/blackberry-mango-refresher.png"}', '{"mocktail_oz":0,"light_oz":0.1,"regular_oz":0.2,"strong_oz":0.3,"raw":"Mocktail = 0 oz., Light = 0.1 oz., Regular = 0.2 oz., Strong = 0.3 oz"}', 'https://bartesian.com/products/blackberry-mango-capsules?variant=46120106295495', 'https://bartesian.gorgias.help/en-US/blackberry-mango-refresher-(us-only)-4332578', '8602390331591', '46120106295495', 'blackberry-mango-capsules', '75683', '4332578', 1, 0, 1, 0, 0, '2026-10-31T00:00:00.000Z', '2026-10-31T00:00:00.000Z');
