INSERT INTO cocktails (id, slug, name, description, details, image, hero_image, marketing_image, image_cut, glassware, garnish, pairs_with, nutrition_json, alcohol_json, bartesian_url, help_url, shopify_product_id, shopify_variant_id, shopify_handle, shopify_sku, gorgias_article_id, seasonal, favorite, enabled, quantity, restock, created_at, updated_at) VALUES (80, 'strawberry-acai-refresher', 'Strawberry Acai Refresher (US Only)', 'When you need refreshment, look no further. Flavors of lush strawberry and tangy acai blend in a perfect balance of sweet and tart. Lightly caffeinated to give you a gentle boost and with an intentionally lower alcohol level than our other offerings, this Refresher lets you sip back, relax, and brighten your day with every vibrant drop. Shake and serve over ice in a highball glass, garnished with strawberry slices.', 'Contains ~56 mg of caffeine. Base spirit: Vodka. Try it as a mocktail!', 'images/marketing/strawberry-acai-refresher.jpg', '', 'images/marketing/strawberry-acai-refresher.jpg', 'NA', 'Highball Glass', 'ed with strawberry slices', '', '{"label_image":"images/nutrition/strawberry-acai-refresher.png"}', '{"mocktail_oz":0,"light_oz":0.1,"regular_oz":0.2,"strong_oz":0.3,"raw":"Mocktail = 0 oz., Light = 0.1 oz., Regular = 0.2 oz., Strong = 0.3 oz"}', 'https://bartesian.com/products/strawberry-acai-capsules?variant=46118504988871', 'https://bartesian.gorgias.help/en-US/strawberry-acai-refresher-(us-only)-4332574', '8602165870791', '46118504988871', 'strawberry-acai-capsules', '75681', '4332574', 1, 0, 1, 0, 0, '2026-10-31T00:00:00.000Z', '2026-10-31T00:00:00.000Z');
