INSERT INTO packs (id, slug, name, notes, image, nutrition_image, bartesian_url, help_url, shopify_product_id, shopify_variant_id, shopify_handle, gorgias_article_id, enabled, created_at, updated_at) VALUES (1, 'advent-calendar-2026', 'Advent Calendar 2026', 'With 3 NEW holiday cocktails and 9 returning festive favorites, you can enjoy a delicious cocktail surprise for 12 nights during the most wonderful time of the year. NEW for 2026: Berry & Bright, Frosted Ambrosia, Salted Caramel Espresso Martini. See the spoiler article for full capsule descriptions.', 'images/packs/advent-calendar-2026.jpg', '', 'https://bartesian.com/products/advent-calendar?variant=47520593445063', 'https://bartesian.gorgias.help/en-US/2026-advent-calendar-(spoiler-alert)-7886629', '8913630003399', '47520593445063', 'advent-calendar', '7886629', 1, '2026-10-31T00:00:00.000Z', '2026-10-31T00:00:00.000Z');
