INSERT INTO packs (id, slug, name, notes, image, nutrition_image, bartesian_url, help_url, shopify_product_id, shopify_variant_id, shopify_handle, gorgias_article_id, enabled, created_at, updated_at) VALUES (2, 'berry-in-love-collection', 'Berry in Love Collection', 'The most charming way to sip, savor, and celebrate love this season? The bright and fruity Bartesian Berry in Love Collection. This limited-edition variety pack contains 4 each of 2 playful pours: - Cupid''s Arrow: the sweet, fruity flavors of strawberry, guava and lime will make your heart skip a beat. - Love Potion: sweet and tart, this enchanting blend includes juicy blueberry, zesty lemon, and delicate lavender flavors.', '', '', '', '', '', '', '', '', 1, '2026-10-31T00:00:00.000Z', '2026-10-31T00:00:00.000Z');
