INSERT INTO packs (id, slug, name, notes, image, nutrition_image, bartesian_url, help_url, shopify_product_id, shopify_variant_id, shopify_handle, gorgias_article_id, enabled, created_at, updated_at) VALUES (3, 'classic-collection-favorites', 'Classic Collection Favorites', 'All of our classics are together in one collection. The Classic Collection Favorites Variety Pack contains 1 each of: - Cosmopolitan: a classic vodka cocktail with tart cranberry, sweet orange, and lime. - Old Fashioned: a spirit-forward whiskey cocktail balancing bitter and sweet with flavors of oak and orange citrus. - Rum Breeze: a sweet, tropical rum cocktail blending pineapple, lime, and strawberry juices, with a hint of coconut flavor. - Lemon Drop: a sweet and tart, lemon candy-inspired vodka martini. - Espresso Martini: a smooth, sippable vodka cocktail with flavors of rich and creamy espresso and bold coffee liqueur. - Margarita: a classic, refreshing tequila cocktail with lemon and lime. - Whiskey Sour: a smooth, citrusy whiskey cocktail with vanilla, lemon, and orange flavors. -', 'images/packs/classic-collection-favorites.jpg', '', 'https://bartesian.com/products/classic-cocktails-favorites?variant=44303522562247', '', '8119625941191', '44303522562247', 'classic-cocktails-favorites', '', 1, '2026-10-31T00:00:00.000Z', '2026-10-31T00:00:00.000Z');
