INSERT INTO packs (id, slug, name, notes, image, nutrition_image, bartesian_url, help_url, shopify_product_id, shopify_variant_id, shopify_handle, gorgias_article_id, enabled, created_at, updated_at) VALUES (5, 'cocktail-sampler-variety-pack', 'Cocktail Sampler Variety Pack', 'Four of Bartesian''s best-selling cocktail capsule varieties. Each capsule is mixologist-designed for taste with real juices, extracts, and bitters and no artificial colors or ingredients. Our 4-pack sampler contains 1 each of: - Lemon Drop: a sweet and tart, lemon candy-inspired vodka martini. - Rum Breeze: a sweet, tropical rum cocktail blending pineapple, lime, and strawberry juices, with a hint of coconut flavor. - Margarita: a classic, refreshing tequila cocktail with lemon and lime. - Whiskey Sour: a smooth, citrusy whiskey cocktail with vanilla, lemon, and orange flavors.', 'images/packs/cocktail-sampler.jpg', '', 'https://bartesian.com/products/cocktail-sampler?variant=44436485046471', '', '8166638452935', '44436485046471', 'cocktail-sampler', '', 1, '2026-10-31T00:00:00.000Z', '2026-10-31T00:00:00.000Z');
