INSERT INTO packs (id, slug, name, notes, image, nutrition_image, bartesian_url, help_url, shopify_product_id, shopify_variant_id, shopify_handle, gorgias_article_id, enabled, created_at, updated_at) VALUES (6, 'festive-collection-2025', 'Festive Collection 2025', 'Get in the festive spirit with this year’s Bartesian Festive Collection. This limited-edition variety pack features merry cocktails across two-spirit types, especially convenient for the Duet Cocktail Maker. This limited-edition variety pack contains 2 each of 4 curated seasonal cocktails: - Starry Night: a refreshing tequila cocktail with flavors of starfruit, grapefruit, guanabana, and citrus. - Peary Christmas: an elegant tequila cocktail with sweet pear, citrus, and delicate almond flavors. - The Grinch Appletini: a shimmering sweet and tart vodka cocktail with green apple flavors. - Frosted Orchard: a crisp vodka cocktail blending juicy apple and tangy lemonade, infused with flavors of cinnamon and cardamom.', '', '', '', '', '', '', '', '', 1, '2026-10-31T00:00:00.000Z', '2026-10-31T00:00:00.000Z');
