INSERT INTO packs (id, slug, name, notes, image, nutrition_image, bartesian_url, help_url, shopify_product_id, shopify_variant_id, shopify_handle, gorgias_article_id, enabled, created_at, updated_at) VALUES (7, 'gin-lovers', 'Gin Lovers (EU/UK)', 'Four of Bartesian’s most-loved gin cocktails, crafted by expert mixologists for exceptional taste. Each capsule is made with real juices, extracts, bitters and no artificial colours or ingredients. This variety pack contains 2 each of 4 cocktails: - Uptown Rocks: an elegant gin cocktail featuring peach and lemon with a graceful kick of cilantro flavour. - Bramble: sweet yet tart, blending blackberry, lemon, and floral flavours for a refreshing classic. - Vesper: a sophisticated gin-and-vodka martini with a smooth balance of bitter, sweet, and herbal flavours. - Aviation: a violet-hued favourite, combining floral Crème de Violette and Maraschino liqueur flavours with a squeeze of lemon.', 'images/packs/gin-lovers.jpg', '', 'https://bartesian.com/products/gin-lovers-collection?variant=39601114775751', '', '6631991574727', '39601114775751', 'gin-lovers-collection', '', 0, '2026-10-31T00:00:00.000Z', '2026-10-31T00:00:00.000Z');
