INSERT INTO packs (id, slug, name, notes, image, nutrition_image, bartesian_url, help_url, shopify_product_id, shopify_variant_id, shopify_handle, gorgias_article_id, enabled, created_at, updated_at) VALUES (8, 'gin-lovers-variety-pack', 'Gin Lovers Variety Pack', 'Calling all gin lovers! Try this refreshing and unique spirit with some of the most beloved gin cocktails in our collection. Our 8-pack contains 2 each of: - Aviation: a floral and sweet classic with flavors of violet, maraschino liqueur, and lemon. - Bee''s Knees: a sweet, citrus cocktail blending lemon with delicate and floral honey flavors. - Raspberry Ginger Gimlet: a bright, raspberry and ginger flavored twist on the classic lime and gin cocktail. - Uptown Rocks: an elegant lemon and peach cocktail with a graceful, cilantro flavored kick.', 'images/packs/gin-lovers.jpg', '', 'https://bartesian.com/products/gin-lovers-collection?variant=39601114775751', '', '6631991574727', '39601114775751', 'gin-lovers-collection', '', 1, '2026-10-31T00:00:00.000Z', '2026-10-31T00:00:00.000Z');
