INSERT INTO packs (id, slug, name, notes, image, nutrition_image, bartesian_url, help_url, shopify_product_id, shopify_variant_id, shopify_handle, gorgias_article_id, enabled, created_at, updated_at) VALUES (9, 'halloween-collection', 'Halloween Collection', 'The best way for you and your ghoulish guests to raise spirits this season? The spine-chillingly delicious Bartesian Halloween Collection. This limited-edition variety pack contains 2 each of 4 curated seasonal cocktails: - Witch''s Heart: a magical martini swirling berry and green apple flavors with edible shimmer. - Caramel Appletini: a wickedly smooth cocktail with tart green apple and rich, velvety caramel flavors. - Sour Spell: a sweet cocktail with a mischievous glow and a burst of sour rainbow candy flavor. - Vampire''s Kiss: a deep crimson cocktail evoking the unmistakable flavor of strawberry licorice. Enjoy this spooky seasonal release while it lasts. Base spirit: Vodka', 'images/packs/halloween-collection.jpg', '', 'https://bartesian.com/products/halloween-collection?variant=46632550432967', '', '8726360719559', '46632550432967', 'halloween-collection', '', 1, '2026-10-31T00:00:00.000Z', '2026-10-31T00:00:00.000Z');
