INSERT INTO packs (id, slug, name, notes, image, nutrition_image, bartesian_url, help_url, shopify_product_id, shopify_variant_id, shopify_handle, gorgias_article_id, enabled, created_at, updated_at) VALUES (10, 'holiday-collection-2025', 'Holiday Collection 2025', 'The best way for you and your holiday guests to get into the spirit of the season is with this year’s Bartesian Holiday Collection. This limited-edition variety pack contains 2 each of 4 curated seasonal cocktails: - Holiday Spiced Old Fashioned: a spirit-forward whiskey cocktail with flavors of orange, bitters, cinnamon and brown sugar. - Clausmopolitan: a shimmering version of the classic cranberry, lime, and orange flavored vodka cocktail. - Peary Christmas: an elegant tequila cocktail with sweet pear, citrus, and delicate almond flavors. - Yuletide Hurricane: a fruity, tropical rum cocktail with added shimmer.', '', '', '', '', '', '', '', '', 1, '2026-10-31T00:00:00.000Z', '2026-10-31T00:00:00.000Z');
