INSERT INTO packs (id, slug, name, notes, image, nutrition_image, bartesian_url, help_url, shopify_product_id, shopify_variant_id, shopify_handle, gorgias_article_id, enabled, created_at, updated_at) VALUES (11, 'lemon-drop-variety-pack', 'Lemon Drop Variety Pack', 'Calling all Lemon Drop fans! Our popular Lemon Drop variety pack is back with four fruit-forward twists on the candy-inspired vodka martini. Shake with ice, serve in a martini glass, rim with lemon sugar, and garnish with lemon. Our 8-pack contains 2 each of: - Strawberry Lemon Drop: sweet and tart with flavors of juicy strawberry and candied lemon. - Blueberry Lemon Drop: jammy blueberry balanced with bright citrus flavor. - Prickly Pear Lemon Drop: prickly pear and zesty lemon, with a hint of hibiscus flavor. - Blue Raspberry Lemon Drop: tangy and sweet with blue raspberry and lemon candy-inspired flavors. Base spirit: Vodka.', 'images/packs/lemon-drop-variety-pack.jpg', '', 'https://bartesian.com/products/lemon-drop-variety-pack?variant=46107183710407', '', '8599659675847', '46107183710407', 'lemon-drop-variety-pack', '', 0, '2026-10-31T00:00:00.000Z', '2026-10-31T00:00:00.000Z');
