INSERT INTO packs (id, slug, name, notes, image, nutrition_image, bartesian_url, help_url, shopify_product_id, shopify_variant_id, shopify_handle, gorgias_article_id, enabled, created_at, updated_at) VALUES (14, 'low-cal-variety-pack', 'Low-Cal Variety Pack', 'Bartesian''s Low-Cal Variety Pack features the same great taste of four of our classic cocktail offerings with no added sugar. Our 8-pack contains 2 each of: - Low-Cal Margarita: a classic, refreshing tequila cocktail with lemon and lime. 10 calories per capsule. - Low-Cal Cosmopolitan: a classic vodka cocktail with tart cranberry, sweet orange, and lime. 15 calories per capsule. - Low-Cal Whiskey Sour: a smooth, citrusy whiskey cocktail with vanilla, lemon, and orange notes. 5 calories per capsule. - Low-Cal Old Fashioned: a spirit-forward whiskey cocktail balancing bitter and sweet with notes of oak and orange citrus. 5 calories per capsule.', 'images/packs/low-cal-variety-pack.jpg', '', 'https://bartesian.com/products/low-cal-variety-pack?variant=43436826165447', '', '7779393568967', '43436826165447', 'low-cal-variety-pack', '', 1, '2026-10-31T00:00:00.000Z', '2026-10-31T00:00:00.000Z');
