INSERT INTO packs (id, slug, name, notes, image, nutrition_image, bartesian_url, help_url, shopify_product_id, shopify_variant_id, shopify_handle, gorgias_article_id, enabled, created_at, updated_at) VALUES (15, 'margarita-lovers', 'Margarita Lovers (EU/UK)', 'Four of Bartesian''s best-selling margaritas, crafted by expert mixologists for exceptional taste. Each capsule is made with real juices, extracts, bitters and no artificial colours or ingredients. This variety pack contains 2 each of 4 cocktails: - Blackberry Margarita: a rich and juicy blend of blackberry and lime with flavours of honeyed fig. - Pineapple Margarita: bursting with tropical pineapple and tart lime, balanced with sweet coconut and orange triple sec flavours. - Pomegranate Margarita: sweet, jammy pomegranate with a splash of lime,and triple sec flavour. - Margarita: a refreshing mix of lemon and lime for the perfect timeless serve.', '', '', '', '', '', '', '', '', 0, '2026-10-31T00:00:00.000Z', '2026-10-31T00:00:00.000Z');
