INSERT INTO packs (id, slug, name, notes, image, nutrition_image, bartesian_url, help_url, shopify_product_id, shopify_variant_id, shopify_handle, gorgias_article_id, enabled, created_at, updated_at) VALUES (16, 'naughty-collection-2025', 'Naughty Collection 2025', 'This kind of naughty will get you on everyone''s nice list. Get in the holiday spirit with this year’s Bartesian Naughty Collection. This limited-edition variety pack contains 2 each of 4 curated seasonal cocktails: - Jollypeño Margarita: a margarita bursting with flavors of vibrant pineapple, zesty lime, and a kick of jalapeño. - Yuletide Hurricane: a fruity, tropical rum cocktail with added shimmer. - Ginger Pear Noel: a tantalizing whiskey cocktail with ripe pear and lime juice, plus a kick of fiery ginger flavor. - The Grinch Appletini: a shimmering sweet and tart vodka cocktail with green apple flavors.', '', '', '', '', '', '', '', '', 1, '2026-10-31T00:00:00.000Z', '2026-10-31T00:00:00.000Z');
