INSERT INTO packs (id, slug, name, notes, image, nutrition_image, bartesian_url, help_url, shopify_product_id, shopify_variant_id, shopify_handle, gorgias_article_id, enabled, created_at, updated_at) VALUES (17, 'nice-collection-2025', 'Nice Collection 2025', 'The Bartesian Nice Collection is the gift that keeps on giving all holiday season long... but nobody said being nice means you have to share. This limited-edition variety pack contains 2 each of 4 curated holiday cocktails: - Brown Butter Old Fashioned: a rich, spirit-forward sipper infused with flavors of indulgent browned butter, bitters and a hint of orange. - Winter Pear-adise: a sweet and tart gin cocktail, blending flavors of juicy pear, earthy sage and a twist of lime. - Frosty Navel: a vibrant vodka cocktail with tangy orange and juicy peach flavors. - Mistletoe Margarita: a blend of jammy pomegranate and baking spice flavors for the perfect seasonal margarita.', '', '', '', '', '', '', '', '', 1, '2026-10-31T00:00:00.000Z', '2026-10-31T00:00:00.000Z');
