INSERT INTO packs (id, slug, name, notes, image, nutrition_image, bartesian_url, help_url, shopify_product_id, shopify_variant_id, shopify_handle, gorgias_article_id, enabled, created_at, updated_at) VALUES (19, 'refreshers-collection', 'Refreshers Collection (US Only)', 'Refreshers are your anytime pick-me-up: crafted to be enjoyed primarily as mocktails, lightly caffeinated and bursting with vibrant, juicy fruit flavors. With an intentionally lower alcohol level than our other offerings, they deliver a lighter, effortlessly refreshing sip. Just shake, pour over ice in a highball glass, and top with fresh fruit. Our 8-pack contains 2 each of: - Strawberry Acai: lush strawberry and tangy acai flavors blend in a perfect balance of sweet and tart. - Pineapple Passion Fruit: juicy pineapple and passion fruit come together in a drink that''s pure tropical bliss. - Blackberry Mango: ripe blackberry meets sweet mango in a smooth, fruit-forward blend that''s as vibrant as it is satisfying. - Peach Lychee: juicy peach and delicate lychee flavors unite in a drink that', 'images/packs/refreshers-collection.jpg', '', 'https://bartesian.com/products/refreshers-collection?variant=45626534265031', '', '8513335820487', '45626534265031', 'refreshers-collection', '', 1, '2026-10-31T00:00:00.000Z', '2026-10-31T00:00:00.000Z');
