INSERT INTO packs (id, slug, name, notes, image, nutrition_image, bartesian_url, help_url, shopify_product_id, shopify_variant_id, shopify_handle, gorgias_article_id, enabled, created_at, updated_at) VALUES (22, 'staff-picks-collection', 'Staff Picks Collection', 'Handpicked by our team, the Staff Picks Collection is an easy crowd-pleaser for any gathering. This variety pack contains 2 each of 4 curated cocktails: - Raspberry Ginger Gimlet: a classic gin cocktail gets a twist with flavors of sweet raspberry and a tangy ginger zing. - Jalapeño Lime Shrub: a refreshing and sour tequila cocktail, with lime, apple cider vinegar, and jalapeño flavors. - Lychee Martini: delicately fruity and lightly floral, this vodka martini is inspired by the tropical, Southeast Asian fruit. - White Sangria: a lively rum-based cocktail with flavors of sweet peach, triple sec, and buttery white wine. Base spirit(s): Gin, Tequila, Vodka, Rum.', 'images/packs/staff-picks-collection.jpg', '', 'https://bartesian.com/products/staff-picks-collection?variant=46171816493255', '', '8616008286407', '46171816493255', 'staff-picks-collection', '', 1, '2026-10-31T00:00:00.000Z', '2026-10-31T00:00:00.000Z');
