INSERT INTO packs (id, slug, name, notes, image, nutrition_image, bartesian_url, help_url, shopify_product_id, shopify_variant_id, shopify_handle, gorgias_article_id, enabled, created_at, updated_at) VALUES (23, 'tropical-margarita', 'Tropical Margarita', 'Calling all margarita lovers! Enjoy a variety of your favorite tequila cocktails with Bartesian’s Tropical Collection. Grab some ice, salt, and lime for garnish, and you’ll be instantly transported to sunshine and a beach chair with a refreshing drink in your hand. Our eight-pack contains two of each of the following: - Blackberry Margarita: a juicy, jammy blend with slightly tart berry flavors and undertones of honeyed fig. - Mango Margarita: a fruity, juicy blend with mango and lime flavors. - Passion Fruit Margarita: a sweet, tropical and tangy blend with passion fruit and citrus flavors. - Pineapple Margarita: a refreshing blend of tart pineapple, sweet coconut and lime flavors.', 'images/packs/tropical-margarita.jpg', '', 'https://bartesian.com/products/tropical-margarita-collection?variant=43136777289927', '', '7646682644679', '43136777289927', 'tropical-margarita-collection', '', 0, '2026-10-31T00:00:00.000Z', '2026-10-31T00:00:00.000Z');
