INSERT INTO packs (id, slug, name, notes, image, nutrition_image, bartesian_url, help_url, shopify_product_id, shopify_variant_id, shopify_handle, gorgias_article_id, enabled, created_at, updated_at) VALUES (27, 'whiskey-lovers', 'Whiskey Lovers (EU/UK)', 'For the whiskey lover in your life. Our 8-count pack contains 2 each of: - Manhattan: a mix of savory, sweet vermouth and aromatic bitters flavors with a hint of cherry. - Old Fashioned: a spirit-forward cocktail balancing bitter and sweet with notes of oak and orange citrus. - Whiskey Sour: a smooth, citrusy whiskey cocktail with vanilla, lemon, and orange notes. - Sidecar: a balanced sour and sweet cocktail with lemon and notes of triple sec.', 'images/packs/whiskey-lovers.jpg', '', 'https://bartesian.com/products/whiskey-lovers-collection?variant=32387435167793', '', '4756368326705', '32387435167793', 'whiskey-lovers-collection', '', 0, '2026-10-31T00:00:00.000Z', '2026-10-31T00:00:00.000Z');
