INSERT INTO packs (id, slug, name, notes, image, nutrition_image, bartesian_url, help_url, shopify_product_id, shopify_variant_id, shopify_handle, gorgias_article_id, enabled, created_at, updated_at) VALUES (29, 'winter-tequila-collection-2025', 'Winter Tequila Collection 2025', 'Embrace the magic of the season with Bartesian''s Winter Tequila Collection, designed to bring warmth and cheer to your winter festivities. This limited-edition variety pack contains 2 each of 4 curated seasonal tequila cocktails: - Jollypeño Margarita: a margarita bursting with flavors of vibrant pineapple, zesty lime, and a kick of jalapeño. - Starry Night: a refreshing tequila cocktail with flavors of starfruit, grapefruit, guanabana and citrus. - Peary Christmas: an elegant tequila cocktail with sweet pear, citrus and delicate almond flavors. - Mistletoe Margarita: a blend of jammy pomegranate and baking spice flavors for the perfect seasonal margarita.', '', '', '', '', '', '', '', '', 1, '2026-10-31T00:00:00.000Z', '2026-10-31T00:00:00.000Z');
