INSERT INTO packs (id, slug, name, notes, image, nutrition_image, bartesian_url, help_url, shopify_product_id, shopify_variant_id, shopify_handle, gorgias_article_id, enabled, created_at, updated_at) VALUES (30, 'winter-vodka-collection-2025', 'Winter Vodka Collection 2025', 'Discover the crisp elegance of Bartesian''s Winter Vodka Collection, designed to bring a touch of sophistication to the frosty season. This limited-edition variety pack contains 2 each of 4 curated seasonal vodka cocktails: - Frosted Orchard: a crisp vodka cocktail blending juicy apple and tangy lemonade, infused with flavors of cinnamon and cardamom. - Clausmopolitan: a shimmering version of the classic cranberry, lime, and orange flavored vodka cocktail. - Frosty Navel: a vibrant vodka cocktail with tangy orange and juicy peach flavors. - The Grinch Appletini: a shimmering sweet and tart vodka cocktail with green apple flavors.', '', '', '', '', '', '', '', '', 1, '2026-10-31T00:00:00.000Z', '2026-10-31T00:00:00.000Z');
